(()=>{'use strict';const hero=document.querySelector('.cinema-hero'),button=document.querySelector('#cinema-motion');if(!hero||!button)return;const reduce=matchMedia('(prefers-reduced-motion:reduce)'),fine=matchMedia('(hover:hover) and (pointer:fine)');let paused=false,frame=0,x=0,y=0;const off=()=>paused||reduce.matches||document.documentElement.classList.contains('motion-off');function reset(){cancelAnimationFrame(frame);frame=0;hero.style.setProperty('--cinema-x','0px');hero.style.setProperty('--cinema-y','0px')}function sync(){if(off())reset();button.textContent=off()?'เอฟเฟกต์ปิดอยู่':'หยุดเอฟเฟกต์';button.setAttribute('aria-pressed',String(off()));button.disabled=reduce.matches||document.documentElement.classList.contains('motion-off')}hero.addEventListener('pointermove',e=>{if(off()||!fine.matches||e.pointerType==='touch')return;const r=hero.getBoundingClientRect();x=((e.clientX-r.left)/r.width-.5)*-14;y=((e.clientY-r.top)/r.height-.5)*-8;if(!frame)frame=requestAnimationFrame(()=>{frame=0;if(off())return;hero.style.setProperty('--cinema-x',x+'px');hero.style.setProperty('--cinema-y',y+'px')})},{passive:true});hero.addEventListener('pointerleave',reset);button.addEventListener('click',()=>{paused=!paused;sync()});reduce.addEventListener('change',sync);new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['class']});sync()})();
